CATEGORIES = sorted({entry.category for entry in COMMANDS})

def search_commands(query="", category="All Categories"):
    terms = query.lower().split()
    return [
        entry for entry in COMMANDS
        if (category == "All Categories" or entry.category == category)
        and all(
            term in (
                entry.category + " " + entry.syntax + " "
                + entry.description
            ).lower()
            for term in terms
        )
    ]
